 "content": "from collections import Counter


def transform(grid):
    """Extract the non-background marker color from each 3x3 panel."""
    out = []
    for br in range(0, len(grid), 3):
        row = []
        for bc in range(0, len(grid[0]), 3):
            counts = Counter(
                grid[r][c]
                for r in range(br, min(br + 3, len(grid)))
                for c in range(bc, min(bc + 3, len(grid[0])))
                if grid[r][c] not in (0, 5)
            )
            row.append(counts.most_common(1)[0][0] if counts else 0)
        out.append(row)
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
